export function useBreadcrumbs(): Crumb[] {
  const { pathname, search } = useLocation()
  const params = new URLSearchParams(search)

  const crumbs: Crumb[] = [{ label: 'Главная', href: '/' }]

  if (pathname === '/catalog') {
    const catId = params.get('cat')
    const view = params.get('view')

    if (view === 'favs') {
      crumbs.push({ label: 'Избранные услуги' })
    } else if (catId) {
      const cat = categories.find((c) => c.id === catId)
      crumbs.push({ label: 'Каталог услуг', href: '/catalog?view=list' })
      crumbs.push({ label: cat?.title ?? 'Категория' })
    } else if (view === 'list') {
      crumbs.push({ label: 'Все услуги' })
    } else {
      crumbs.push({ label: 'Каталог услуг' })
    }
  } else if (pathname.startsWith('/service/')) {
    const id = pathname.replace('/service/', '')
    const svc = services.find((s) => s.id === id)
    crumbs.push({ label: 'Каталог услуг', href: '/catalog' })
    if (svc) {
      crumbs.push({
        label: svc.categoryTitle,
        href: `/catalog?cat=${svc.category}&view=list`,
      })
      crumbs.push({ label: svc.shortTitle })
    } else {
      crumbs.push({ label: 'Услуга' })
    }
  } else if (pathname === '/apps') {
    crumbs.push({ label: 'Мои услуги' })
  } else if (pathname === '/notifications') {
    crumbs.push({ label: 'Мои уведомления' })
  } else if (pathname === '/profile') {
    crumbs.push({ label: 'Личный кабинет' })
  } else if (pathname === '/support') {
    crumbs.push({ label: 'Поддержка' })
  } else if (pathname === '/about') {
    crumbs.push({ label: 'О портале' })
  } else if (pathname === '/login') {
    crumbs.push({ label: 'Вход' })
  }

  return crumbs
}



import { useMemo, useState } from 'react'
import { searchServices, suggestServices } from '../lib/search'
import type { Service } from '../types/service'

/** Подсказки для autocomplete с дебаунсом, чтобы не дёргать поиск на каждый символ. */
export function useSuggestions(query: string, delay = 120) {
  const [debounced, setDebounced] = useState(query)

  useMemo(() => {
    const t = setTimeout(() => setDebounced(query), delay)
    return () => clearTimeout(t)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [query, delay])

  return useMemo(() => {
    if (!debounced.trim()) return []
    return suggestServices(debounced, 6)
  }, [debounced])
}

/** Полный поиск (для страницы каталога). */
export function useSearchResults(query: string): Service[] {
  return useMemo(() => searchServices(query).map((h) => h.service), [query])
}



import { useCallback, useEffect, useState } from 'react'
import type { Application } from '../types/service'

const APPS_KEY = 'epasluga-apps'

const SEED: Application[] = [
  { id: 'a1', num: '453346557107272', title: 'Справка о доходах', serviceId: '3-05-03', initiator: 'Министерство по налогам и сборам', status: 'Выполнено', at: new Date().toISOString(), comment: '' },
  { id: 'a2', num: '289953663290680', title: 'Справка о доходах', serviceId: '3-05-03', initiator: 'Министерство по налогам и сборам', status: 'Ожидает оплаты', at: new Date().toISOString(), comment: '' },
  { id: 'a3', num: '100294837561002', title: 'Паспорт гражданина РБ', serviceId: '200-12-1', initiator: 'Министерство внутренних дел', status: 'На проверке', at: new Date(Date.now() - 86400000).toISOString(), comment: '' },
  { id: 'a4', num: '100294837561088', title: 'Регистрация автомобиля', serviceId: '200-15-11', initiator: 'Министерство внутренних дел', status: 'Черновик', at: new Date(Date.now() - 2 * 86400000).toISOString(), comment: '' },
  { id: 'a5', num: '100294837561201', title: 'Справка призывнику', serviceId: '200-20-5', initiator: 'Министерство обороны', status: 'Отозвано', at: new Date(Date.now() - 4 * 86400000).toISOString(), comment: '' },
  { id: 'a6', num: '100294837561333', title: 'Лицензия адвоката', serviceId: '200-17-1-1', initiator: 'Министерство юстиции', status: 'Отказано', at: new Date(Date.now() - 8 * 86400000).toISOString(), comment: 'Неполный комплект документов' },
]

function read(): Application[] {
  try {
    const raw = JSON.parse(localStorage.getItem(APPS_KEY) || 'null')
    if (Array.isArray(raw)) return raw
  } catch { /* ignore */ }
  localStorage.setItem(APPS_KEY, JSON.stringify(SEED))
  return SEED
}

function write(rows: Application[]) {
  localStorage.setItem(APPS_KEY, JSON.stringify(rows))
}

export function useApplications() {
  const [apps, setApps] = useState(() => read())

  useEffect(() => {
    const onStorage = (e: StorageEvent) => { if (e.key === APPS_KEY) setApps(read()) }
    window.addEventListener('storage', onStorage)
    return () => window.removeEventListener('storage', onStorage)
  }, [])

  const update = useCallback((id: string, patch: Partial) => {
    setApps((prev) => {
      const next = prev.map((a) => (a.id === id ? { ...a, ...patch } : a))
      write(next)
      return next
    })
  }, [])

  const remove = useCallback((id: string) => {
    setApps((prev) => {
      const next = prev.filter((a) => a.id !== id)
      write(next)
      return next
    })
  }, [])

  return { apps, update, remove }
}



import type { Application } from '../types/service'

export function downloadDemoPdf(app: Application) {
  const body = `E-Pasluga demo document\nApplication ${app.num}\n${app.title}\nStatus: ${app.status}\n`

  // Минимальный валидный PDF-контент (из legacy)
  const pdf = `%PDF-1.1
1 0 obj<< /Type /Catalog /Pages 2 0 R >>endobj
2 0 obj<< /Type /Pages /Kids [3 0 R] /Count 1 >>endobj
3 0 obj<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Contents 4 0 R /Resources<< /Font<< /F1 5 0 R >> >> >>endobj
4 0 obj<< /Length 120 >>stream
BT /F1 12 Tf 50 780 Td (${body.replace(/[()\\]/g, ' ').replace(/\n/g, ') Tj T* (')}) Tj ET
endstream
endobj
5 0 obj<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>endobj
xref
0 6
0000000000 65535 f 
0000000009 00000 n 
0000000058 00000 n 
0000000115 00000 n 
0000000266 00000 n 
0000000437 00000 n 
trailer<< /Size 6 /Root 1 0 R >>
startxref
510
%%EOF`

  const blob = new Blob([pdf], { type: 'application/pdf' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = `dokument-${app.num}.pdf`
  document.body.appendChild(a)
  a.click()
  document.body.removeChild(a)
  URL.revokeObjectURL(url)
}



import { useCallback, useEffect, useState } from 'react'

const FAV_KEY = 'epasluga-favs'

function readFavs(): Set {
  try {
    const raw = JSON.parse(localStorage.getItem(FAV_KEY) || '[]')
    if (Array.isArray(raw)) return new Set(raw)
  } catch {
    // ignore corrupt storage
  }
  return new Set()
}

function writeFavs(set: Set) {
  localStorage.setItem(FAV_KEY, JSON.stringify([...set]))
}

/** Хук избранного с синхронизацией между вкладками. */
export function useFavorites() {
  const [favs, setFavs] = useState<Set>(() => readFavs())

  useEffect(() => {
    const onStorage = (e: StorageEvent) => {
      if (e.key === FAV_KEY) setFavs(readFavs())
    }
    window.addEventListener('storage', onStorage)
    return () => window.removeEventListener('storage', onStorage)
  }, [])

  const toggle = useCallback((id: string) => {
    setFavs((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      writeFavs(next)
      return next
    })
  }, [])

  const has = useCallback((id: string) => favs.has(id), [favs])

  return { favs, toggle, has }
}



import type { ApplicationStatus } from '../types/service'

export function formatWhen(iso: string): string {
  const d = new Date(iso)
  const now = new Date()
  const start = (x: Date) => new Date(x.getFullYear(), x.getMonth(), x.getDate()).getTime()
  const diff = Math.round((start(now) - start(d)) / 86400000)
  if (diff === 0) return 'Сегодня'
  if (diff === 1) return 'Вчера'
  return d.toLocaleDateString('ru-BY', { day: 'numeric', month: 'long', year: 'numeric' })
}

export function statusClass(st: ApplicationStatus): string {
  if (st === 'Выполнено') return 'bg-[#e6f6ec] text-ok'
  if (st === 'Ожидает оплаты') return 'bg-[#fff4e5] text-accent-warm'
  if (st === 'Черновик') return 'bg-soft text-muted'
  if (st === 'На проверке') return 'bg-[#e8eeff] text-navy'
  if (st === 'Отозвано') return 'bg-[#f4f4f5] text-[#52525b]'
  if (st === 'Отказано') return 'bg-[#fdecea] text-danger'
  return 'bg-soft text-muted'
}

export function statusHelp(st: ApplicationStatus): string {
  if (st === 'Отозвано') return 'Вы отменили заявление. Документ по нему не выдадут.'
  if (st === 'Отказано') return 'Ведомство не оказало услугу. Причину смотрите в комментарии.'
  if (st === 'Ожидает оплаты') return 'Заявление принято, но без оплаты документ не выдадут.'
  if (st === 'Черновик') return 'Вы ещё не отправили заявление.'
  return ''
}



import { useCallback, useEffect, useState } from 'react'
import type { AppNotification } from '../types/service'

const NOTIF_KEY = 'epasluga-notifs'

const SEED: AppNotification[] = [
  { id: 'n1', kind: 'legal', title: 'Справка о доходах — Готово', body: 'Документ можно скачать в разделе «Мои услуги».', at: new Date().toISOString(), archived: false },
  { id: 'n2', kind: 'legal', title: 'Справка о доходах — Ожидает оплаты', body: 'Заявление 289953663290680 не будет выдано, пока не поступит оплата.', at: new Date().toISOString(), archived: false },
  { id: 'n3', kind: 'legal', title: 'Справка призывнику — Отозвано', body: 'Вы отменили заявление. Документ не действует.', at: new Date(Date.now() - 4 * 86400000).toISOString(), archived: false },
  { id: 'n4', kind: 'legal', title: 'Лицензия адвоката — Отказано', body: 'Ведомство не смогло оказать услугу. Причина указана в «Моих услугах».', at: new Date(Date.now() - 8 * 86400000).toISOString(), archived: false },
  { id: 'n5', kind: 'info', title: 'Плановые работы 1 ноября', body: 'Ночью кабинет может быть недоступен около двух часов.', at: new Date(Date.now() - 86400000).toISOString(), archived: false },
  { id: 'n6', kind: 'info', title: 'Черновик заявления не отправлен', body: 'Регистрация авто сохранена как черновик.', at: new Date(Date.now() - 2 * 86400000).toISOString(), archived: false },
]

function read(): AppNotification[] {
  try {
    const raw = JSON.parse(localStorage.getItem(NOTIF_KEY) || 'null')
    if (Array.isArray(raw)) return raw
  } catch { /* ignore */ }
  localStorage.setItem(NOTIF_KEY, JSON.stringify(SEED))
  return SEED
}

function write(rows: AppNotification[]) {
  localStorage.setItem(NOTIF_KEY, JSON.stringify(rows))
}

export function useNotifications() {
  const [items, setItems] = useState(() => read())

  useEffect(() => {
    const onStorage = (e: StorageEvent) => { if (e.key === NOTIF_KEY) setItems(read()) }
    window.addEventListener('storage', onStorage)
    return () => window.removeEventListener('storage', onStorage)
  }, [])

  const archive = useCallback((id: string) => {
    setItems((prev) => { const next = prev.map((n) => n.id === id ? { ...n, archived: true } : n); write(next); return next })
  }, [])

  const unarchive = useCallback((id: string) => {
    setItems((prev) => { const next = prev.map((n) => n.id === id ? { ...n, archived: false } : n); write(next); return next })
  }, [])

  const remove = useCallback((id: string) => {
    setItems((prev) => { const next = prev.filter((n) => n.id !== id || n.kind === 'legal'); write(next); return next })
  }, [])

  return { items, archive, unarchive, remove }
}



import { services } from '../data/services'
import { synonyms } from '../data/synonyms'
import type { Service } from '../types/service'

/** Нормализация: нижний регистр, ё→е, схлопывание пробелов. */
export function normalize(s: string): string {
  return (s || '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/\s+/g, ' ')
    .trim()
}

/** Собираем поисковый «блоб» для каждой услуги один раз. */
const index: Array<{ service: Service; blob: string; shortBlob: string }> = services.map((s) => ({
  service: s,
  blob: normalize(
    [s.shortTitle, s.officialTitle, s.code, s.orgName, s.categoryTitle].join(' '),
  ),
  shortBlob: normalize(s.shortTitle),
}))

/** Совпадения по синонимам: возвращает Set кодов услуг, которые надо подмешать. */
function synonymHits(query: string): Set {
  const q = normalize(query)
  const hits = new Set()
  if (!q) return hits

  for (const [key, ids] of Object.entries(synonyms)) {
    const k = normalize(key)
    // совпадение в обе стороны: «доход» ⊂ «доходы» и наоборот
    if (k.includes(q) || q.includes(k)) {
      ids.forEach((id) => hits.add(id))
    }
  }
  return hits
}

export type SearchHit = {
  service: Service
  /** 0 — прямое совпадение по короткому названию, 1 — синоним, 2 — по описанию, 3 — по коду */
  rank: number
}

export function searchServices(query: string): SearchHit[] {
  const q = normalize(query)
  if (!q) return services.map((service) => ({ service, rank: 2 }))

  const synHits = synonymHits(q)
  const result: SearchHit[] = []

  for (const { service, blob, shortBlob } of index) {
    if (shortBlob.includes(q)) {
      result.push({ service, rank: 0 })
    } else if (synHits.has(service.code) || synHits.has(service.id)) {
      result.push({ service, rank: 1 })
    } else if (blob.includes(q)) {
      result.push({ service, rank: 2 })
    } else if (normalize(service.code).includes(q)) {
      result.push({ service, rank: 3 })
    }
  }

  result.sort((a, b) => a.rank - b.rank || a.service.shortTitle.localeCompare(b.service.shortTitle))
  return result
}

/** Топ-N подсказок для выпадающего списка. */
export function suggestServices(query: string, limit = 6): Service[] {
  return searchServices(query).slice(0, limit).map((h) => h.service)
}



