:root {
  --navy: #2f3bbd;
  --navy-deep: #1e2a8a;
  --ink: #1a1d2b;
  --muted: #5a6078;
  --line: #e2e5f0;
  --bg: #f3f4f8;
  --card: #ffffff;
  --soft: #eef0f8;
  --danger: #b42318;
  --ok: #17663d;
  --shadow: 0 10px 30px rgba(30, 42, 120, 0.07);
  --radius: 14px;
  --sidebar-w: 248px;
  --rail: 96px;
  --font: 'Segoe UI', 'PT Sans', 'Roboto', Arial, sans-serif;
}

* {
  box-sizing: border-box;
}
html,
body {
  margin: 0;
  min-height: 100%;
}
body {
  font-family: var(--font);
  color: var(--ink);
  background: var(--bg);
  font-size: 15.5px;
  line-height: 1.5;
}

.app {
  display: block;
  min-height: 100vh;
  padding-left: var(--rail);
}

.sidebar {
  background: var(--navy);
  color: #fff;
  position: fixed;
  left: 0;
  top: 0;
  bottom: 0;
  width: var(--rail);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  z-index: 40;
  transition: width 0.2s ease;
}
.sidebar:hover,
.sidebar:focus-within {
  width: var(--sidebar-w);
  box-shadow: 10px 0 32px rgba(20, 24, 80, 0.22);
  overflow: auto;
}
.brand {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 18px 8px 14px;
  text-decoration: none;
  color: #fff;
  font-weight: 700;
  font-size: 20px;
  min-height: 72px;
  white-space: nowrap;
}
.sidebar:hover .brand,
.sidebar:focus-within .brand {
  justify-content: flex-start;
  padding: 18px 16px 14px;
}
.brand-mark {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  flex: 0 0 32px;
  background: conic-gradient(from 200deg, #7dd3fc, #86efac, #93c5fd, #7dd3fc);
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.35);
}
.brand-short {
  font-size: 16px;
  letter-spacing: 0.04em;
  font-weight: 800;
}
.brand-text {
  opacity: 0;
  width: 0;
  overflow: hidden;
  pointer-events: none;
}
.brand-sub,
.nav-label,
.nav-item > span:not(.nav-caret),
.nav-sub span {
  opacity: 0;
  white-space: nowrap;
  overflow: hidden;
  max-width: 0;
  margin: 0;
  padding: 0;
  pointer-events: none;
  flex: 0 0 0;
}
.sidebar:hover .brand-short,
.sidebar:focus-within .brand-short {
  display: none;
}
.sidebar:hover .brand-text,
.sidebar:focus-within .brand-text {
  opacity: 1;
  width: auto;
  pointer-events: auto;
}
.sidebar:hover .brand-sub,
.sidebar:focus-within .brand-sub,
.sidebar:hover .nav-label,
.sidebar:focus-within .nav-label {
  opacity: 1;
  max-width: none;
  pointer-events: auto;
  flex: 0 0 auto;
}
.sidebar:hover .nav-item > span:not(.nav-caret),
.sidebar:focus-within .nav-item > span:not(.nav-caret),
.sidebar:hover .nav-sub span,
.sidebar:focus-within .nav-sub span {
  opacity: 1;
  max-width: 280px;
  pointer-events: auto;
  flex: 1 1 auto;
  overflow: visible;
