  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.55);
}
.sidebar:hover .nav-label,
.sidebar:focus-within .nav-label {
  height: auto;
  margin: 10px 18px 4px;
}
