export function ServicePage() {
  const { id } = useParams()
  const service = services.find((s) => s.id === id)
  const [isFormOpen, setIsFormOpen] = useState(false)

  if (!service) {
    return (



Услуга не найдена

          Вернуться в каталог


    )
  }

  if (isFormOpen) {
    return  setIsFormOpen(false)} />
  }

  return (


      {/* Шапка с заголовком */}



{service.shortTitle}


          {service.authLevel === 'id' && Нужна ID-карта}
          {service.authLevel === 'ecp' && Нужна ЭЦП}
          {service.authLevel === 'none' && Без ID-карты}
          {service.code}
          · {service.orgName}



      {/* Сетка: контент + сайдбар (на мобильных сайдбар уходит в самый низ) */}



        {/* Левая колонка (Основная информация) */}



          {/* 1. Что это */}



Что это

{service.plainDescription}


          {/* 2. Что вы получите */}



{ru.service.resultTitle}




                ⏱ {ru.service.timeLabel}
                {service.timeToComplete}



                💰 {ru.service.costLabel}
                {service.cost}



                📄 {ru.service.formatLabel}
                {service.format}




          {/* 3. Как это работает */}



Как это работает

              {service.steps.map((step, i) => (



                    {i + 1}

                  {step}

              ))}



          {/* 4. Официальное название (скрыто в аккордеон) */}



              Код услуги: {service.code}



              Полное наименование:{' '}
              {service.officialTitle}



              Ведомство: {service.orgName} (УНП{' '}
              {service.orgUnp})




        {/* Правая колонка (Сайдбар с действием) */}
        {/* На мобильных мы хотим, чтобы он был внизу, поэтому убираем sticky на мобильных */}





            {/* Кнопка Заказать (спокойная, не агрессивная) */}


Оформление

{AUTH_HINT[service.authLevel]}
               setIsFormOpen(true)}
                className="w-full bg-white! text-navy! hover:bg-soft! border-0 font-bold"
              >
                {ru.service.orderButton}



            {/* Ведомство (под кнопкой) */}



                Кто оказывает услугу


{service.orgName}

УНП: {service.orgUnp}






